function getFlag(code) {
  const c = CURRENCY_COUNTRY[code];
  if (!c) return "";
  if (c === "EU") return String.fromCodePoint(0x1F1EA, 0x1F1FA);
  return Array.from(c).map(x => String.fromCodePoint(0x1F1E6 + x.charCodeAt(0) - 65)).join("");
}

const st = { from:"USD", to:"EUR", rates:[], currentRate:0, selectedRate:0, rateDate:Math.floor(Date.now()/1000), period:24, chart:null, fetchError:false };

function makeDropdown(which) {
  const trigger  = document.getElementById(which+"-trigger");
  const dropdown = document.getElementById(which+"-dropdown");
  const search   = document.getElementById(which+"-search");
  const list     = document.getElementById(which+"-list");

  function opts() { return which==="from" ? Object.keys(CURRENCY_PAIRS).sort() : (CURRENCY_PAIRS[st.from]||[]).slice().sort(); }
  function cur()  { return which==="from" ? st.from : st.to; }

  function render(q) {
    const filtered = opts().filter(o => !q || o.includes(q.toUpperCase()));
    list.innerHTML = "";
    if (!filtered.length) { list.innerHTML = "<div class=\"cc-empty\">No results</div>"; return; }
    const frag = document.createDocumentFragment();
    filtered.forEach(code => {
      const d = document.createElement("div");
      d.className = "cc-option" + (code===cur()?" selected":"");
      const flagSpan = document.createElement("span");
      flagSpan.className = "opt-flag";
      flagSpan.textContent = getFlag(code);
      const codeSpan = document.createElement("span");
      codeSpan.textContent = code;
      d.appendChild(flagSpan); d.appendChild(codeSpan);
      d.addEventListener("mousedown", e => { e.preventDefault(); pick(code); });
      frag.appendChild(d);
    });
    list.appendChild(frag);
    const sel = list.querySelector(".selected");
    if (sel) sel.scrollIntoView({block:"nearest"});
  }

  function open() {
    closeAll();
    dropdown.classList.add("open"); trigger.classList.add("open");
    search.value = ""; render(""); setTimeout(() => search.focus(), 10);
  }
  function close() { dropdown.classList.remove("open"); trigger.classList.remove("open"); }

  function pick(code) {
    if (which==="from") {
      st.from = code;
      const tos = (CURRENCY_PAIRS[code]||[]).slice().sort();
      if (!tos.includes(st.to)) st.to = tos[0]||"";
      setTrigger("from"); setTrigger("to");
    } else {
      st.to = code; setTrigger("to");
    }
    close(); resetCalc(); fetchRates();
  }

  trigger.addEventListener("click", () => dropdown.classList.contains("open") ? close() : open());
  search.addEventListener("input", () => render(search.value));
  search.addEventListener("keydown", e => { if(e.key==="Escape") close(); });
}

function closeAll() {
  document.querySelectorAll(".cc-dropdown").forEach(d => d.classList.remove("open"));
  document.querySelectorAll(".cc-trigger").forEach(t => t.classList.remove("open"));
}
document.addEventListener("click", e => { if (!e.target.closest(".cc-wrap")) closeAll(); });

function setTrigger(w) {
  const code = w==="from" ? st.from : st.to;
  document.getElementById(w+"-flag").textContent = getFlag(code);
  document.getElementById(w+"-code").textContent = code;
}

document.getElementById("swap-btn").addEventListener("click", () => {
  const pf=st.from, pt=st.to;
  st.from = pt;
  const tos = (CURRENCY_PAIRS[pt]||[]).slice().sort();
  st.to = tos.includes(pf) ? pf : (tos[0]||"");
  setTrigger("from"); setTrigger("to");
  resetCalc(); fetchRates();
});

async function fetchRates() {
  document.getElementById("chart-loader").style.display = "flex";
  document.getElementById("chart-empty").classList.remove("show");
  document.getElementById("amount-suffix").textContent = st.from;
  const base = "https://fx-processors.prod.niumops.com/"+st.from+"-"+st.to+"-hourly.json";
  const urls = [base,"https://corsproxy.io/?url="+encodeURIComponent(base),"https://api.allorigins.win/raw?url="+encodeURIComponent(base)];
  let data = null;
  for (const url of urls) { try { const r=await fetch(url); if(r.ok){data=await r.json();break;} } catch(e){} }
  if (data && data.exchangeRates && data.exchangeRates.length) {
    st.rates = data.exchangeRates.map(r=>({...r,time_unix:Math.floor(new Date(r.time).getTime()/1000)}));
    st.fetchError = false;
    st.currentRate = parseFloat(st.rates[st.rates.length-1].average);
    findRate();
  } else { st.rates=[]; st.currentRate=0; st.selectedRate=0; st.fetchError=true; }
  updateRateDisplay(); renderChart();
  document.getElementById("chart-loader").style.display = "none";
}

function findRate() {
  if (!st.rates.length) { st.selectedRate=0; return; }
  st.selectedRate = parseFloat(st.rates[st.rates.length-1].average);
  for (let i=0; i<st.rates.length; i++) {
    if (st.rates[i].time_unix >= st.rateDate && i>0) { st.selectedRate=parseFloat(st.rates[i-1].average); break; }
  }
}

function effectiveRate() { return st.selectedRate||st.currentRate; }

function updateRateDisplay() {
  const rate=effectiveRate();
  const rl=document.getElementById("current-rate-line"), nb=document.getElementById("interbank-note");
  if (rate) {
    rl.innerHTML = "Current rate 1 "+st.from+" = <strong>"+parseFloat(rate).toPrecision(7)+" "+st.to+"</strong>";
    nb.innerHTML = "Interbank rate on this date <strong>1 "+st.from+" = "+parseFloat(rate).toPrecision(10)+" "+st.to+"</strong>";
  } else { rl.textContent="No rate data available"; nb.textContent=""; }
}

function renderChart() {
  const empty=document.getElementById("chart-empty");
  if (!st.rates.length) {
    empty.textContent = st.fetchError
      ? "Unable to load rate data — CORS restriction. Serve this page from your Laravel app to bypass it."
      : "No rate data available for "+st.from+"–"+st.to+".";
    empty.classList.add("show");
    if (st.chart) { st.chart.destroy(); st.chart=null; }
    return;
  }
  empty.classList.remove("show");
  const period=Math.min(st.period,st.rates.length);
  const sliced=st.rates.slice(Math.max(0,st.rates.length-period-1));
  const serData=sliced.map(r=>[r.time,r.average]);
  const vals=sliced.map(r=>r.average);
  const minA=Math.min(...vals), maxA=Math.max(...vals);
  const spread=maxA===minA?minA/2:maxA-minA;
  const last=st.rates[st.rates.length-1];
  document.getElementById("last-update-time").textContent=moment(last.time).fromNow();
  const isDaily=period>48, wide=window.innerWidth>768;
  const opts={
    series:[{name:"Rate",data:serData}],colors:["#7162CF"],
   //changed this below line from old js
    chart:{type:"line",height:"100%",zoom:{enabled:false},toolbar:{show:false},background:"#F9F9FD",animations:{enabled:true,speed:350}},
//    chart:{type:"line",height:wide?300:180,zoom:{enabled:false},toolbar:{show:false},background:"#F9F9FD",animations:{enabled:true,speed:350}},
    dataLabels:{enabled:false},stroke:{curve:"straight",width:2},markers:{size:0},
    grid:{borderColor:"#E4E4F0",strokeDashArray:3},
    yaxis:{min:minA-spread/6,max:maxA+spread/6,show:wide,labels:{formatter:v=>v.toPrecision(6)},tickAmount:wide?7:4},
    xaxis:{type:"datetime",
      labels:isDaily?{formatter:v=>new Date(v).toLocaleDateString("en-US",{day:"2-digit",month:"short"})}:{formatter:v=>String(new Date(v).getUTCHours()).padStart(2,"0")+":00"},
      tickAmount:wide?(period<=48?12:period>2000?10:7):5},
    tooltip:{y:{formatter:v=>v.toPrecision(6)},x:{formatter:v=>{const d=new Date(v);return d.toLocaleString("default",{month:"short",timeZone:"UTC"})+" "+d.getUTCDate()+" "+String(d.getUTCHours()).padStart(2,"0")+":"+String(d.getUTCMinutes()).padStart(2,"0")+" UTC";}}},
    annotations:{points:[{x:moment(last.time).valueOf(),y:effectiveRate(),marker:{size:4,fillColor:"#24BAD6",strokeColor:"#24BAD6",radius:2}}]}
  };
  if (st.chart) { st.chart.updateOptions({series:opts.series,yaxis:opts.yaxis,xaxis:opts.xaxis,annotations:opts.annotations}); }
  else { st.chart=new ApexCharts(document.getElementById("fx-chart"),opts); st.chart.render(); }
}

function resetCalc() {
  ["result-box","instruction-note"].forEach(id=>document.getElementById(id).classList.remove("show"));
  ["vendor-error","amount-error"].forEach(id=>document.getElementById(id).classList.remove("show"));
  ["vendor-rate","amount"].forEach(id=>document.getElementById(id).classList.remove("error"));
}

document.getElementById("calc-btn").addEventListener("click",()=>{
  const ae=document.getElementById("amount"), ve=document.getElementById("vendor-rate");
  const amt=parseFloat(ae.value), ven=parseFloat((ve.value||"").replace(",","."));
  let ok=true;
  if (!ae.value||isNaN(amt)||amt<1){document.getElementById("amount-error").classList.add("show");ae.classList.add("error");ok=false;}
  else{document.getElementById("amount-error").classList.remove("show");ae.classList.remove("error");}
  if (!ve.value||isNaN(ven)||ven<0){document.getElementById("vendor-error").classList.add("show");ve.classList.add("error");document.getElementById("instruction-note").classList.add("show");ok=false;}
  else{document.getElementById("vendor-error").classList.remove("show");ve.classList.remove("error");document.getElementById("instruction-note").classList.remove("show");}
  if (!ok){document.getElementById("result-box").classList.remove("show");return;}
  const rate=effectiveRate(); if(!rate)return;
  const mr=rate-ven, markup=mr*amt, pct=((mr/rate)*100).toFixed(2);
  document.getElementById("result-markup").textContent=new Intl.NumberFormat("en-US",{minimumFractionDigits:2,maximumFractionDigits:4}).format(Math.abs(markup));
  document.getElementById("result-markup").className="result-value "+(markup>=0?"positive":"negative");
  document.getElementById("result-pct-badge").textContent=pct+"%";
  document.getElementById("result-box").classList.add("show");
});
[document.getElementById("amount"),document.getElementById("vendor-rate")].forEach(el=>el.addEventListener("keydown",e=>{if(e.key==="Enter")document.getElementById("calc-btn").click();}));

(function(){
  const now=new Date(),pad=n=>String(n).padStart(2,"0"),el=document.getElementById("rate-datetime");
  el.value=now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate())+"T"+pad(now.getHours())+":"+pad(now.getMinutes());
  el.max=el.value;
  document.getElementById("utc-note").textContent=pad(now.getUTCHours())+":"+pad(now.getUTCMinutes())+" UTC";
})();

document.getElementById("rate-datetime").addEventListener("change",function(){
  const d=new Date(this.value),pad=n=>String(n).padStart(2,"0");
  st.rateDate=Math.floor(d.getTime()/1000);
  document.getElementById("utc-note").textContent=pad(d.getUTCHours())+":"+pad(d.getUTCMinutes())+" UTC";
  findRate(); updateRateDisplay(); resetCalc(); renderChart();
});

document.querySelectorAll(".period-tab").forEach(btn=>btn.addEventListener("click",()=>{
  document.querySelectorAll(".period-tab").forEach(b=>b.classList.remove("active"));
  btn.classList.add("active"); st.period=parseInt(btn.dataset.period); renderChart();
}));

